def transform(g):
    h=len(g); w=len(g[0])
    sr=[i for i in range(h) if all(x==8 for x in g[i])]
    sc=[j for j in range(w) if all(g[i][j]==8 for i in range(h))]
    def bands(seps,n):
        b=[];s=0
        for x in seps+[n]: b.append((s,x)); s=x+1
        return b
    rb=bands(sr,h); cb=bands(sc,w)
    # seed coordinates per color, in (band idx, block idx)
    seeds={2:[],3:[]}
    for bi,(r0,r1) in enumerate(rb):
        for bj,(c0,c1) in enumerate(cb):
            for i in range(r0,r1):
                for j in range(c0,c1):
                    if g[i][j] in seeds: seeds[g[i][j]].append((bi,bj))
    fill={2:set(),3:set()}  # set of (bi,bj)
    for col,S in seeds.items():
        from collections import defaultdict
        rowsd=defaultdict(list); colds=defaultdict(list)
        for bi,bj in S:
            rowsd[bi].append(bj); colds[bj].append(bi)
        for bi,js in rowsd.items():
            for bj in range(min(js),max(js)+1): fill[col].add((bi,bj))
        for bj,is_ in colds.items():
            for bi in range(min(is_),max(is_)+1): fill[col].add((bi,bj))
    BW=cb[0][1]-cb[0][0]; BH=rb[0][1]-rb[0][0]
    def full(bi,bj):
        r0,r1=rb[bi]; c0,c1=cb[bj]
        return r1-r0==BH and c1-c0==BW
    out=[row[:] for row in g]
    for bi in range(len(rb)):
        for bj in range(len(cb)):
            if not full(bi,bj): continue
            r0,r1=rb[bi]; c0,c1=cb[bj]
            has2=(bi,bj) in fill[2]; has3=(bi,bj) in fill[3]
            if has2 and has3: v=6
            elif has2: v=2
            elif has3: v=3
            else: continue
            for i in range(r0,r1):
                for j in range(c0,c1): out[i][j]=v
    return out
